export type PromptTemplate = {
  slug: string;
  title: string;
  useCase: string;
  whenToUse: string;
  promptText: string;
  tips: string[];
  goodOutputLooksLike: string;
  redFlag: string;
};

export type PromptCategory = {
  slug: string;
  name: string;
  icon: string;
  description: string;
  moduleLink: string;
  prompts: PromptTemplate[];
};

