export function getAllPrompts(): (PromptTemplate & { category: string; categorySlug: string })[] {
  return promptCategories.flatMap((cat) =>
    cat.prompts.map((p) => ({ ...p, category: cat.name, categorySlug: cat.slug }))
  );
}
